//! Small string helpers mirroring the internal helpers of the C++ library.

/// ASCII lowercase copy, equivalent to `std::transform(..., ::tolower)` in the
/// "C" locale (bytes >= 0x80 are left untouched).
pub fn to_lower(s: &str) -> String {
    s.bytes()
        .map(|b| (if b.is_ascii_uppercase() { b + 32 } else { b }) as char)
        .collect()
}

/// Trim leading/trailing whitespace, matching `std::isspace` in the "C" locale.
pub fn trim(s: &str) -> &str {
    let b = s.as_bytes();
    let mut start = 0;
    while start < b.len() && is_c_space(b[start]) {
        start += 1;
    }
    let mut end = b.len();
    while end > start && is_c_space(b[end - 1]) {
        end -= 1;
    }
    &s[start..end]
}

/// `std::isspace` for the "C" locale: space, \t, \n, \v, \f, \r.
fn is_c_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

pub fn is_hex(c: u8) -> bool {
    c.is_ascii_digit() || (b'a'..=b'f').contains(&c) || (b'A'..=b'F').contains(&c)
}

pub fn hex_to_char(c: u8) -> i32 {
    if c.is_ascii_digit() {
        (c - b'0') as i32
    } else if (b'a'..=b'f').contains(&c) {
        (c - b'a') as i32 + 10
    } else if (b'A'..=b'F').contains(&c) {
        (c - b'A') as i32 + 10
    } else {
        -1
    }
}

/// Faithful re-implementation of `std::stoi(s)` (base 10).
///
/// Skips leading whitespace, accepts an optional sign, consumes the leading run
/// of decimal digits and ignores any trailing characters. Returns `None` where
/// the C++ version would throw: `std::invalid_argument` when no digits are
/// present, `std::out_of_range` when the value does not fit in an `int`.
pub fn stoi(s: &str) -> Option<i32> {
    let b = s.as_bytes();
    let mut i = 0;

    while i < b.len() && is_c_space(b[i]) {
        i += 1;
    }

    let negative = match b.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let digits_start = i;
    let mut value: i64 = 0;
    let mut overflow = false;
    while i < b.len() && b[i].is_ascii_digit() {
        if !overflow {
            value = value * 10 + (b[i] - b'0') as i64;
            // Once past the int range the result can never come back, so cap
            // the accumulator to keep it far away from i64 overflow.
            if value > u32::MAX as i64 {
                overflow = true;
            }
        }
        i += 1;
    }

    if i == digits_start {
        return None; // std::invalid_argument
    }
    if overflow {
        return None; // std::out_of_range
    }

    let signed = if negative { -value } else { value };
    if signed < i32::MIN as i64 || signed > i32::MAX as i64 {
        return None; // std::out_of_range
    }
    Some(signed as i32)
}

