//! Standalone component validators (`url_parser::is_*_valid`).

/// A scheme must be non-empty, start with an ASCII letter and continue with
/// letters, digits, `+`, `-` or `.` (RFC 3986 `scheme`). Comparison is
/// case-insensitive, i.e. upper-case schemes are accepted as-is.
pub fn is_scheme_valid(scheme: &str) -> bool {
    let b = scheme.as_bytes();
    if b.is_empty() {
        return false;
    }
    if !b[0].is_ascii_alphabetic() {
        return false;
    }
    b[1..]
        .iter()
        .all(|&c| c.is_ascii_alphanumeric() || c == b'+' || c == b'-' || c == b'.')
}

/// A host must be non-empty and made only of ASCII alphanumerics, `-`, `.` and
/// the IPv6 literal brackets `[` / `]`. No length, label or dot-placement rules
/// are applied, and any byte >= 0x80 is rejected.
pub fn is_host_valid(host: &str) -> bool {
    let b = host.as_bytes();
    if b.is_empty() {
        return false;
    }
    b.iter().all(|&c| {
        c.is_ascii_alphanumeric() || c == b'-' || c == b'.' || c == b'[' || c == b']'
    })
}

/// Ports are valid over the whole 16-bit range including 0; the sentinel `-1`
/// used for "no port" therefore reads as invalid.
pub fn is_port_valid(port: i32) -> bool {
    (0..=65535).contains(&port)
}

