//! The `url_parser::URL` type: a permissive, purely lexical URL splitter.

use super::util::stoi;
use super::validate::{is_host_valid, is_port_valid, is_scheme_valid};

/// Value stored in `port` when the URL carries no usable port.
const NO_PORT: i32 = -1;

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Url {
    scheme: String,
    userinfo: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl Url {
    pub fn new() -> Self {
        Url {
            port: NO_PORT,
            ..Default::default()
        }
    }

    /// Equivalent of `url_parser::URL parser(url)`.
    pub fn from_url(url: &str) -> Self {
        let mut u = Url::new();
        u.parse(url);
        u
    }

    /// Splits `url` into components. The grammar is deliberately lenient: no
    /// component is validated here, nothing is trimmed, unescaped or
    /// case-folded, and a missing separator simply yields an empty component.
    pub fn parse(&mut self, url: &str) {
        *self = Url::new();
        let mut rest = url;

        // Fragment, then query: both are stripped from the right before the
        // hierarchical part is examined.
        if let Some(i) = rest.find('#') {
            self.fragment = rest[i + 1..].to_string();
            rest = &rest[..i];
        }
        if let Some(i) = rest.find('?') {
            self.query = rest[i + 1..].to_string();
            rest = &rest[..i];
        }

        // Only an explicit "://" introduces an authority. Without it the whole
        // remainder is the path, so "example.com" and "//host/x" are paths.
        let Some(i) = rest.find("://") else {
            self.path = rest.to_string();
            return;
        };
        self.scheme = rest[..i].to_string();
        let after = &rest[i + 3..];

        let (authority, path) = match after.find('/') {
            Some(j) => (&after[..j], &after[j..]),
            None => (after, ""),
        };
        self.path = path.to_string();

        // userinfo is split off at the *first* '@', so any later '@' stays in
        // the host (and makes it invalid).
        let host_port = match authority.find('@') {
            Some(k) => {
                self.userinfo = authority[..k].to_string();
                &authority[k + 1..]
            }
            None => authority,
        };

        // Likewise the *first* ':' ends the host; the tail is fed to stoi,
        // which tolerates trailing junk but rejects a digitless string. This is
        // why "[::1]:8080" ends up with host "[" and no port.
        match host_port.find(':') {
            Some(m) => {
                self.host = host_port[..m].to_string();
                self.port = stoi(&host_port[m + 1..]).unwrap_or(NO_PORT);
            }
            None => self.host = host_port.to_string(),
        }
    }

    /// A URL is considered valid as long as it locates something: it needs
    /// either an authority host or a path. Scheme, query and fragment alone are
    /// not enough, which is why "http://" and "?q=1" are rejected.
    pub fn is_valid(&self) -> bool {
        !self.host.is_empty() || !self.path.is_empty()
    }

    /// Static convenience check, `url_parser::URL::is_valid_url`.
    pub fn is_valid_url(url: &str) -> bool {
        Url::from_url(url).is_valid()
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn userinfo(&self) -> &str {
        &self.userinfo
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn has_scheme(&self) -> bool {
        !self.scheme.is_empty()
    }

    pub fn has_userinfo(&self) -> bool {
        !self.userinfo.is_empty()
    }

    pub fn has_host(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_port(&self) -> bool {
        self.port != NO_PORT
    }

    pub fn has_authority(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_path(&self) -> bool {
        !self.path.is_empty()
    }

    pub fn has_query(&self) -> bool {
        !self.query.is_empty()
    }

    pub fn has_fragment(&self) -> bool {
        !self.fragment.is_empty()
    }

    /// The authority as it would be re-serialised: `[userinfo@]host[:port]`.
    pub fn authority(&self) -> String {
        let mut out = String::new();
        if !self.userinfo.is_empty() {
            out.push_str(&self.userinfo);
            out.push('@');
        }
        out.push_str(&self.host);
        if self.has_port() {
            out.push(':');
            out.push_str(&self.port.to_string());
        }
        out
    }

    pub fn scheme_is_valid(&self) -> bool {
        is_scheme_valid(&self.scheme)
    }

    pub fn host_is_valid(&self) -> bool {
        is_host_valid(&self.host)
    }

    pub fn port_is_valid(&self) -> bool {
        is_port_valid(self.port)
    }
}

impl std::fmt::Display for Url {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.has_scheme() {
            write!(f, "{}://", self.scheme)?;
        }
        write!(f, "{}{}", self.authority(), self.path)?;
        if self.has_query() {
            write!(f, "?{}", self.query)?;
        }
        if self.has_fragment() {
            write!(f, "#{}", self.fragment)?;
        }
        Ok(())
    }
}

