mod url_parser;

use std::io::Write;
use url_parser::Url;

/// The C++ program treats `argv` as raw bytes, so a URL that is not valid UTF-8
/// still round-trips to `std::cout` untouched. Rust's `String` cannot hold those
/// bytes directly, so each byte >= 0x80 is escaped to a distinct private-use
/// code point on the way in and restored on the way out. Every delimiter the
/// parser looks for is ASCII and every validator rejects non-ASCII, so the
/// escaped form parses and validates exactly like the original bytes.
const ESCAPE_BASE: u32 = 0xE000;
const ESCAPE_RANGE: std::ops::RangeInclusive<u32> = 0xE080..=0xE0FF;

fn escape_bytes(bytes: &[u8]) -> String {
    bytes
        .iter()
        .map(|&b| {
            if b.is_ascii() {
                b as char
            } else {
                char::from_u32(ESCAPE_BASE + b as u32).expect("private-use code point")
            }
        })
        .collect()
}

fn unescape_bytes(s: &str) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len());
    let mut buf = [0u8; 4];
    for c in s.chars() {
        let cp = u32::from(c);
        if ESCAPE_RANGE.contains(&cp) {
            out.push((cp - ESCAPE_BASE) as u8);
        } else {
            out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
        }
    }
    out
}

#[cfg(unix)]
fn argv() -> Vec<String> {
    use std::os::unix::ffi::OsStrExt;
    std::env::args_os()
        .map(|arg| escape_bytes(arg.as_bytes()))
        .collect()
}

#[cfg(not(unix))]
fn argv() -> Vec<String> {
    std::env::args().collect()
}

/// `std::cout << bool` prints 1 / 0.
fn cout_bool(value: bool) -> u8 {
    u8::from(value)
}

fn main() {
    let args = argv();
    if args.len() < 2 {
        std::process::exit(1);
    }

    let url = &args[1];

    println!("{}", cout_bool(Url::is_valid_url(url)));

    let parser = Url::from_url(url);

    println!("{}", cout_bool(url_parser::is_scheme_valid(parser.scheme())));
    println!("{}", cout_bool(url_parser::is_host_valid(parser.host())));
    println!("{}", cout_bool(url_parser::is_port_valid(parser.port())));

    let path_segments = url_parser::split_path(parser.path());
    println!("{}", path_segments.len());

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for segment in &path_segments {
        out.write_all(&unescape_bytes(segment)).unwrap();
        out.write_all(b"\n").unwrap();
    }
}

